package com.immersio.upload.api; import com.immersio.upload.service.StorageService; import com.immersio.shared.dto.ApiResponse; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.util.*;
@RestController @RequestMapping("/api/upload") public class UploadController {private final StorageService storage;public UploadController(StorageService s){storage=s;}@PostMapping("/image") public ApiResponse<Map<String,String>> image(@RequestParam MultipartFile file,@RequestParam(required=false)String folder)throws IOException{return ApiResponse.successResult(Map.of("url",storage.store(file,folder)));}}
